const debris = scene.tiles.find(
  tile => tile.name === "groundfloor.fragile-floor-debris"
);

if (!debris) return;

await debris.update({ hidden: false });

const debris = scene.tiles.find(
  tile => tile.name === "groundfloor.fragile-floor-debris"
);

if (!debris) return;

await debris.update({ hidden: true });

const fragileFloor = scene.tiles.find(
  tile => tile.name === "firstfloor.fragile-floor"
);

if (!fragileFloor) {
  return;
}

await game.modules
  .get("theiks-toolbag")
  ?.api?.breakableTerrain?.advance?.(fragileFloor);
